class RangeFreqQuery {
    Map<Integer,List<Integer>> positions=new HashMap<>();
    public RangeFreqQuery(int[] arr){
        for(int i=0;i<arr.length;i++)positions.computeIfAbsent(arr[i],ignored->new ArrayList<>()).add(i);
    }
    private int lower(List<Integer> values,int target){
        int left=0,right=values.size();
        while(left<right){
            int middle=(left+right)/2;
            if(values.get(middle)<target)left=middle+1;
            else right=middle;
        }
        return left;
    }
    private int upper(List<Integer> values,int target){
        int left=0,right=values.size();
        while(left<right){
            int middle=(left+right)/2;
            if(values.get(middle)<=target)left=middle+1;
            else right=middle;
        }
        return left;
    }
    public int query(int left,int right,int value){
        List<Integer> values=positions.getOrDefault(value,Collections.emptyList());
        return upper(values,right)-lower(values,left);
    }
}

code.kotlin:
class RangeFreqQuery(arr:IntArray){
    private val positions=HashMap<Int,MutableList<Int>>();
    init{
        for(i in arr.indices)positions.getOrPut(arr[i]){
            mutableListOf()
        }.add(i)
    }
    private fun lower(values:List<Int>,target:Int):Int{
        var left=0;
        var right=values.size;
        while(left<right){
            val middle=(left+right)/2;
            if(values[middle]<target)left=middle+1 else right=middle
        };
        return left
    }
    private fun upper(values:List<Int>,target:Int):Int{
        var left=0;
        var right=values.size;
        while(left<right){
            val middle=(left+right)/2;
            if(values[middle]<=target)left=middle+1 else right=middle
        };
        return left
    }
    fun query(left:Int,right:Int,value:Int):Int{
        val values=positions[value]?:emptyList();
        return upper(values,right)-lower(values,left)
    }
}

